class Solution:
    def medianSlidingWindow(self, nums: List[int], k: int) -> List[float]:
        tree = None
        ans = []
        for i, x in enumerate(nums):
            tree = insert(tree, x)
            if size(tree) > k:
                tree = remove(tree, nums[i - k])
            if size(tree) == k:
                if k % 2 == 1:
                    ans.append(get(tree, k // 2 + 1))
                else:
                    ans.append((get(tree, k // 2) + get(tree, k // 2 + 1)) / 2)
        return ans


def size(node):
    return node[2] if node else 0


def update(node):
    node[2] = 1 + size(node[3]) + size(node[4])
    return node


def split_le(node, key):
    # left: keys <= key, right: keys > key
    if not node:
        return None, None
    if node[0] <= key:
        left, right = split_le(node[4], key)
        node[4] = left
        return update(node), right
    left, right = split_le(node[3], key)
    node[3] = right
    return left, update(node)


def split_lt(node, key):
    # left: keys < key, right: keys >= key
    if not node:
        return None, None
    if node[0] < key:
        left, right = split_lt(node[4], key)
        node[4] = left
        return update(node), right
    left, right = split_lt(node[3], key)
    node[3] = right
    return left, update(node)


def merge(a, b):
    if not a or not b:
        return a or b
    if a[1] > b[1]:
        a[4] = merge(a[4], b)
        return update(a)
    b[3] = merge(a, b[3])
    return update(b)


