    return merge(merge(left, [key, random.random(), 1, None, None]), right)


def remove(node, key):
    left, rest = split_le(node, key)      # left: <= key, rest: > key
    lt, eq = split_lt(left, key)          # lt: < key, eq: roots at key
    eq = merge(eq[3], eq[4])              # drop one occurrence of key
