        track = dict()

        occ = collections.Counter(words)

        def test():
            for key, val in track.items():
                if val != occ[key]:
                    return False
            return True

        res = []
        # first look

        for k in range(wlen):
            for i in words:
                track.update({i: 0})
            for i in range(k, slen + k, wlen):
                w = s[i:i + wlen]
                if w in words:
                    track.update({w: track[w] + 1})
