from typing import List
from collections import defaultdict


class Solution:
    def maxPower(self, stations: List[int], r: int, k: int) -> int:
        start, end = min(stations), sum(stations) + k
        while start + 1 < end:
            mid = (start + end) // 2
            if self.check(stations, r, k, mid):
                start = mid
            else:
                end = mid
        if self.check(stations, r, k, end):
            return end
        else:
            return start

    def check(self, stations, r, k, target):
        n = len(stations)
        ans = True
        newStations = defaultdict(int)
        power = sum(stations[:r])
        for i in range(n):
            if i + r < n:
                power += stations[i + r]
            if i - r - 1 >= 0:
                power -= stations[i - r - 1]
            if power >= target:
                continue
            elif power + k < target:
                ans = False
                break
            else:
                diff = target - power
                power = target
                pos = min(i + r, n - 1)
                stations[pos] += diff
                k -= diff
                newStations[pos] += diff
        for i in newStations:
            stations[i] -= newStations[i]
        return ans
```

The bug: the sweep loop ran `for i in range(n + 1)`, processing a nonexistent city `n`. On that extra iteration the window's left element `stations[n - r - 1]` was subtracted (shrinking `power` below the real value), which could then wrongly consume `k` or return `False` for feasible targets (e.g., `stations = [2,2], r = 0, k = 5` returned 3 instead of 4). Restricting the loop to valid cities `range(n)` fixes it; the window initialization `sum(stations[:r])` combined with the in-loop add of `stations[i + r]` is consistent, the mutation/restore of `stations` via `newStations` is correct, and the binary search bounds/final check are valid.

