class Solution:
    def isPossibleToCutPath(self, grid: List[List[int]]) -> bool:
        m, n = len(grid), len(grid[0])

        def dfs(i, j):
            if i < 0 or j < 0:
                return False
            if grid[i][j] == 0:
                return False
            if i == 0 and j == 0:
                return True
            grid[i][j] = 0
            return dfs(i-1, j) or dfs(i, j-1)

        if not dfs(m-1, n-1):
            return True

        def dfs2(i, j):
            if i >= m or j >= n:
                return False
            if grid[i][j] == 0:
                return False
            if i == m-1 and j == n-1:
                return True
            grid[i][j] = 0
            return dfs2(i+1, j) or dfs2(i, j+1)

        return not dfs2(0, 0)
```

