import bisect

class SegmentTree:
    def __init__(self, N):
        self.n = N
        self.tree = [0] * (2 * N)

    def update(self, pos, value):
        pos += self.n
        self.tree[pos] = value
        while pos > 1:
            pos >>= 1
            self.tree[pos] = max(self.tree[2 * pos], self.tree[2 * pos + 1])

    def query(self, left, right):
        res = 0
        left += self.n
        right += self.n
        while left < right:
            if left & 1:
                res = max(res, self.tree[left])
                left += 1
            if right & 1:
                right -= 1
                res = max(res, self.tree[right])
            left >>= 1
            right >>= 1
        return res

class Solution:
    def maxBalancedSubsequenceSum(self, nums: List[int]) -> int:
        if max(nums) < 0:
            return max(nums)
        vals = sorted(set(x - i for i, x in enumerate(nums)))
        st = SegmentTree(len(vals))
        ans = 0
        for i, x in enumerate(nums):
            pos = bisect.bisect_left(vals, x - i) + 1
            cur = st.query(0, pos) + x
            ans = max(ans, cur)
            st.update(pos, cur)
        return ans

