class Solution:
    def isPossibleToCutPath(self, grid: List[List[int]]) -> bool:
        m, n = len(grid), len(grid[0])
        dirs = [(-1, 0), (0, -1)]
        def dfs(i: int, j: int) -> bool:
            if grid[i][j] != 1: return False
            grid[i][j] = 2
            if i == 0 and j == 0: return True
            for di, dj in dirs:
                if 0 <= i + di < m and 0 <= j + dj < n and dfs(i + di, j + dj): return True
            return False
        if not dfs(m - 1, n - 1): return True
        dq = collections.deque([(0, 0)])
        grid[0][0] = 0
        dirs = [(1, 0), (0, 1)]
        while dq:
            l = len(dq)
            for _ in range(l):
                i, j = dq.popleft()
                if i == m - 1 and j == n - 1: return False
                for di, dj in dirs:
                    if 0 <= i + di < m and 0 <= j + dj < n and grid[i + di][j + dj] == 2:
                        dq.append((i + di, j + dj))
                        grid[i + di][j + dj] = 0
            if len(dq) == 1: return True
        return False
```

